import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const f=JSON.parse('{"title":"FR 3.7.15 — View Collaborator Directory","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/06-ai-features/3-7-15-view-collaborator-directory/spec.md","filePath":"feature/srs/06-ai-features/3-7-15-view-collaborator-directory/spec.md"}'),c={name:"feature/srs/06-ai-features/3-7-15-view-collaborator-directory/spec.md"};function d(n,e,l,i,s,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-7-15-—-view-collaborator-directory" tabindex="-1">FR 3.7.15 — View Collaborator Directory <a class="header-anchor" href="#fr-3-7-15-—-view-collaborator-directory" aria-label="Permalink to &quot;FR 3.7.15 — View Collaborator Directory&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.7.15</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-102</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">View Collaborator Directory</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">AI Features (<code>3.7</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20</code>, <code>BR-51</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01</code>, <code>MSG02</code>, <code>MSG03</code>, <code>MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified (Consolidates <code>partner-directory</code> DA-949 / E50-08)</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Provide a centralized, Agency-scoped Collaborator &amp; Media Partner Directory (<code>/agency/:agencyId/collaborators</code> for full directory administration and <code>/workspaces/:workspaceId/campaign-partners</code> active-only picker) backed by PostgreSQL <code>third_party_collaborators</code> and <code>campaign_collaborators</code> (<code>BR-20</code>, <code>BR-51</code>). Supports categorizing third-party partners (<code>KOL</code>, <code>KOC</code>, <code>NEWSPAPER</code>, <code>BANNER</code>, <code>TV</code>, <code>OTHER</code>), inspecting <code>isActive</code> lifecycle states, <code>canDelete</code> / <code>usageHistoryVerified</code> audit flags, contact metadata, and campaign cooperation links.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an <code>Owner</code> or <code>Manager</code>, I want to browse, search, and filter the Agency&#39;s third-party Collaborator Directory with clear active/inactive badges and campaign usage status so that <code>Owner</code> can govern master partner records across the Agency while <code>Manager</code> can select active partners for Workspace Campaign execution without cross-Agency data leakage.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Dual-Surface Role Authorization (<code>BR-20</code>, <code>BR-51</code>):</strong><ul><li><strong>Agency Management Directory (<code>GET /api/v1/agencies/{agencyId}/collaborators</code>):</strong> Accessible to <code>Owner</code> of <code>{agencyId}</code>, returning paginated active and inactive records (<code>isActive: true | false</code>), <code>version</code>, <code>firstUsedAt</code>, <code>usageHistoryVerified</code>, and computed <code>canDelete</code> + <code>deleteLockReason</code>.</li><li><strong>Workspace Active Picker (<code>GET /api/v1/workspaces/{workspaceId}/collaborators</code> &amp; <code>GET /api/v1/collaborators/agencies/{agencyId}</code>):</strong> Accessible to authorized <code>Owner</code> and <code>Manager</code> in the Workspace/Agency, returning active partners (<code>isActive = true</code>) for campaign linking without exposing cross-Agency records (<code>MSG07</code>).</li><li>Existing linked inactive partners on a Campaign remain readable via <code>GET /api/v1/workspaces/{workspaceId}/campaign-collaborators</code> with an explicit <code>Inactive</code> badge.</li></ul></li><li><strong>Search, Category &amp; Status Filtering:</strong> Supports keyword search (name, niche, notes), partner type filter (<code>KOL</code>, <code>KOC</code>, <code>NEWSPAPER</code>, <code>BANNER</code>, <code>TV</code>, <code>OTHER</code>), status filter (<code>ACTIVE</code>, <code>INACTIVE</code>, <code>ALL</code>), and deterministic pagination.</li><li><strong>Contact Info Structured Rendering:</strong> Safely renders JSONB <code>contactInfo</code> fields (<code>contactPerson</code>, <code>email</code>, <code>phone</code>, <code>website</code>, social handles) while tolerating additional legacy JSON keys.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Uses key-parallel <code>src/i18n/locales/{vi,en}/collaborators.json</code> (<code>title</code>, <code>fields.*</code>, <code>status.active</code>, <code>status.inactive</code>, <code>filters.*</code>, <code>empty</code>, <code>loading</code>) on Web and <code>tr(&#39;collaborators.*&#39;)</code> on Mobile (<code>AgencyCollaboratorsScreen.tsx</code>).</li><li><strong>Light &amp; Dark Mode Compliance:</strong> Partner cards, filter toolbars, active/inactive status pills, and detail drawers (<code>pages/collaborators/page.tsx</code>, <code>DirectoryFilters.tsx</code>, <code>DirectoryResults.tsx</code>, <code>PartnerDetails.tsx</code>) use semantic theme tokens in both Light and Dark modes across <code>375px</code>, <code>768px</code>, and <code>1440px</code>.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces:</strong> <code>/agency/:agencyId/collaborators</code> (<code>pages/collaborators/page.tsx</code>) and <code>/workspaces/:workspaceId/campaign-partners</code> (<code>pages/campaign-partners/page.tsx</code>, <code>PartnerPicker.tsx</code>).</li><li><strong>Mobile Surface:</strong> <code>src/screens/agency/AgencyCollaboratorsScreen.tsx</code> and <code>src/components/campaign/CampaignPartnersSection.tsx</code>.</li><li><strong>UI States:</strong><ul><li><strong>Loading:</strong> Skeleton table/cards (<code>collaborators.loading</code>).</li><li><strong>Empty:</strong> Contextual empty state differentiating &quot;No collaborators created yet&quot; vs &quot;No collaborators match current filter&quot; with reset-filter button.</li><li><strong>Populated:</strong> Paginated partner list with type badge, contact summary, <code>Active</code>/<code>Inactive</code> pill, and lock tooltip explaining why used/legacy partners cannot be hard-deleted.</li><li><strong>Error:</strong> Retryable error banner (<code>MSG03</code> / <code>MSG07</code>) with zero mock fallback rows.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth</th><th style="text-align:left;">Controller</th><th style="text-align:left;">Response</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/agencies/{agencyId}/collaborators</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>DirectoryPartnerController</code></td><td style="text-align:left;"><code>200 ApiResponse&lt;PageResponse&lt;DirectoryPartnerResponse&gt;&gt;</code></td></tr><tr><td style="text-align:left;"><code>GET /api/v1/agencies/{agencyId}/collaborators/{id}</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>DirectoryPartnerController</code></td><td style="text-align:left;"><code>200 ApiResponse&lt;DirectoryPartnerResponse&gt;</code></td></tr><tr><td style="text-align:left;"><code>GET /api/v1/collaborators/agencies/{agencyId}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager</code>)</td><td style="text-align:left;"><code>CollaboratorController</code></td><td style="text-align:left;"><code>200 ApiResponse&lt;List&lt;CollaboratorResponse&gt;&gt;</code></td></tr><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/collaborators</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager</code>)</td><td style="text-align:left;"><code>CampaignCollaboratorController</code></td><td style="text-align:left;"><code>200 ApiResponse&lt;List&lt;CollaboratorOptionResponse&gt;&gt;</code> (active-only picker)</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): Caller belongs to another Agency, or non-Owner attempts full management directory mutation; generic <code>MEMBER</code> status never grants <code>Owner</code> directory privileges.</li><li><code>NOT_FOUND</code> (<code>404</code>, <code>MSG01</code>): Collaborator UUID does not exist or belongs to a different <code>agencyId</code> (prevents ID enumeration).</li><li><strong>Inactive Partner Visibility:</strong> Hidden from new-link active pickers, visible in management directory and on historical Campaign links.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Sibling SRS FRs:</strong> <a href="./../3-7-16-create-collaborator-profile/spec.html">FR 3.7.16 — Create Collaborator Profile</a> · <a href="./../3-7-17-update-collaborator-profile/spec.html">FR 3.7.17 — Update Collaborator Profile</a> · <a href="./../3-7-18-remove-collaborator-profile/spec.html">FR 3.7.18 — Remove Collaborator Profile</a> · <a href="./../3-7-19-recommend-collaborator/spec.html">FR 3.7.19 — Recommend Collaborator</a></li><li><strong>Consolidated Extension Module:</strong> <a href="./../../../modules/03-campaign-package-delivery/campaign-timeline-and-closure/spec.html"><code>campaign-timeline-and-closure</code></a> (<code>campaign_collaborators</code> cooperation tracking)</li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/06-ai-features.html">BA 3.7 AI Features</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> <code>DirectoryPartnerControllerTest</code>, <code>DirectoryPartnerServiceTest</code>, <code>DirectoryPartnerPostgresTest</code> passing (<code>100%</code>), Web &amp; Mobile views localized (<code>vi</code>/<code>en</code>) and Light/Dark verified per <a href="./test.html">test.md</a>.</li><li><strong>Out of Scope:</strong> Automated third-party KOL contract payment disbursement or external social inbox messaging.</li></ul>',19)])])}const h=t(c,[["render",d]]);export{f as __pageData,h as default};
